"use client";

// The agent panel: conversation, tool activity, composer.
//
// Structure follows the AI Elements vocabulary (Conversation → Message → Tool →
// Prompt Input) but is built from this project's own shadcn components. The
// Elements CLI wanted to overwrite components/ui/textarea.tsx, and this repo
// treats components/ui as read-only.
//
// The design bet: tool calls are the interesting content, not chat. A user
// watching the email rebuild itself cares which blocks changed, so tool
// activity renders as compact labelled rows rather than being hidden behind a
// disclosure. Prose from the model is deliberately secondary.

import * as React from "react";
import {
  AlertCircleIcon,
  BrainIcon,
  CheckIcon,
  ChevronDownIcon,
  Loader2Icon,
  SparklesIcon,
  UndoIcon,
} from "lucide-react";

import { ScrollArea } from "@/components/ui/scroll-area";
import { resolveCommandPrompt, type AgentCommand } from "@/lib/agent/commands";
import { summarizeBlock } from "@/lib/agent/tools";
import { useAgent } from "@/lib/agent/use-agent";
import { createId, findBlock, type EmailDocument } from "@/lib/email/document";
import { cn } from "@/lib/utils";

import { AgentComposer } from "./agent-composer";
import { ApiKeyField } from "./api-key-field";

/** Human labels for tool names — "updateBlock" is our jargon, not the user's. */
const TOOL_LABELS: Record<string, string> = {
  readBlock: "Reading",
  addBlock: "Adding a block",
  updateBlock: "Editing",
  setBlockStyle: "Restyling",
  removeBlock: "Removing a block",
  moveBlock: "Reordering",
  duplicateBlock: "Duplicating",
  setCustomHtml: "Writing HTML",
  setDocumentSettings: "Updating the theme",
  setSubject: "Setting the subject",
};

type ToolPart = Record<string, unknown>;

/**
 * The concrete thing a step touched, pulled from the tool's own arguments —
 * "Editing" alone doesn't tell you which block moved, which is the only detail
 * that matters when you're watching an email rebuild itself.
 */
function toolDetail(name: string, input: unknown): string | null {
  if (!input || typeof input !== "object") return null;
  const args = input as Record<string, unknown>;

  const patchKeys = (value: unknown) =>
    value && typeof value === "object" ? Object.keys(value).join(", ") : null;

  switch (name) {
    case "addBlock":
      return typeof args.type === "string" ? args.type : null;
    case "updateBlock":
    case "setBlockStyle":
      return patchKeys(args.patch);
    case "setDocumentSettings":
      return patchKeys(args.patch);
    case "setCustomHtml":
      return typeof args.label === "string" && args.label ? args.label : "custom HTML";
    case "setSubject":
      return typeof args.subject === "string" ? args.subject : "preview text";
    default:
      return typeof args.id === "string" ? args.id : null;
  }
}

function StepRow({ part }: { part: ToolPart }) {
  const name = String(part.type ?? "").replace(/^tool-/, "");
  const state = String(part.state ?? "");
  const done = state === "output-available";
  const failed = state === "output-error" || state === "output-denied";
  const detail = toolDetail(name, part.input);

  return (
    <div className="flex items-start gap-2 py-1 text-xs">
      <span className="mt-0.5 shrink-0">
        {failed ? (
          <AlertCircleIcon className="size-3 text-destructive" />
        ) : done ? (
          <CheckIcon className="size-3 text-emerald-600" />
        ) : (
          <Loader2Icon className="size-3 animate-spin text-muted-foreground" />
        )}
      </span>
      <span className="min-w-0 flex-1">
        <span className={cn("font-medium", failed ? "text-destructive" : "text-foreground/80")}>
          {TOOL_LABELS[name] ?? name}
        </span>
        {detail && <span className="text-muted-foreground"> · {detail}</span>}
        {failed && typeof part.errorText === "string" && (
          <span className="mt-0.5 block text-[11px] text-destructive/80">{part.errorText}</span>
        )}
      </span>
    </div>
  );
}

/**
 * Collapsible record of the steps taken for one message.
 *
 * Open while running so the work is visible, folded once finished so the
 * transcript stays readable — the summary line is what you want afterwards,
 * the detail is there when something looks wrong.
 */
function ChainOfThought({ parts, running }: { parts: ToolPart[]; running: boolean }) {
  const [openOverride, setOpenOverride] = React.useState<boolean | null>(null);
  const open = openOverride ?? running;
  const failed = parts.filter(
    (p) => p.state === "output-error" || p.state === "output-denied",
  ).length;

  const summary = running
    ? "Working…"
    : `${parts.length} ${parts.length === 1 ? "step" : "steps"}${failed ? `, ${failed} failed` : ""}`;

  return (
    <div className="rounded-xl border border-border bg-muted/30">
      <button
        type="button"
        onClick={() => setOpenOverride(!open)}
        className="flex w-full items-center gap-2 px-2.5 py-1.5 text-xs"
      >
        <BrainIcon className="size-3.5 shrink-0 text-muted-foreground" />
        <span className="font-medium">Chain of thought</span>
        <span className="text-muted-foreground">{summary}</span>
        <ChevronDownIcon
          className={cn(
            "ml-auto size-3.5 shrink-0 text-muted-foreground transition-transform",
            open && "rotate-180",
          )}
        />
      </button>
      {open && (
        <div className="border-t border-border/60 px-2.5 py-1">
          {parts.map((part, i) => (
            <StepRow key={String(part.toolCallId ?? i)} part={part} />
          ))}
        </div>
      )}
    </div>
  );
}

/** Placeholder while the model is still deciding what to do. */
function ThinkingBubble() {
  return (
    <div className="flex items-center gap-2 text-xs text-muted-foreground">
      <span className="flex gap-1">
        {[0, 1, 2].map((i) => (
          <span
            key={i}
            className="size-1.5 animate-bounce rounded-full bg-muted-foreground/50"
            style={{ animationDelay: `${i * 140}ms` }}
          />
        ))}
      </span>
      Thinking…
    </div>
  );
}

type MessageLike = {
  id: string;
  role: string;
  parts?: Array<Record<string, unknown>>;
};

function Message({ message, running }: { message: MessageLike; running: boolean }) {
  const isUser = message.role === "user";
  const parts = message.parts ?? [];

  const text = parts
    .filter((p) => p.type === "text")
    .map((p) => String(p.text ?? ""))
    .join("")
    .trim();

  const tools = parts.filter((p) => String(p.type ?? "").startsWith("tool-"));

  if (isUser) {
    return (
      <div className="flex justify-end">
        <div className="max-w-[85%] rounded-2xl rounded-br-sm bg-primary px-3 py-2 text-sm text-primary-foreground">
          {text}
        </div>
      </div>
    );
  }

  if (!text && tools.length === 0) return null;

  // Steps still in flight keep the group open; a finished turn folds itself up.
  const stepsRunning =
    running && tools.some((p) => p.state !== "output-available" && p.state !== "output-error");

  return (
    <div className="flex flex-col gap-2">
      {tools.length > 0 && <ChainOfThought parts={tools} running={stepsRunning} />}
      {text && <p className="text-sm leading-relaxed text-foreground">{text}</p>}
      {/* The model finished its tools but hasn't written its summary yet —
          without this the panel looks frozen at exactly the moment it isn't. */}
      {running && !text && tools.length > 0 && !stepsRunning && <ThinkingBubble />}
    </div>
  );
}

const STARTERS = [
  "Tighten the opening paragraph",
  "Add a call-to-action button at the end",
  "Proofread everything",
];

export function AgentPanel({
  document,
  updateDocument,
  selectedBlockId,
  campaignId,
}: {
  document: EmailDocument;
  updateDocument: (updater: (current: EmailDocument) => EmailDocument) => void;
  /** Canvas selection, auto-attached as context for the next message. */
  selectedBlockId?: string;
  campaignId?: string;
}) {
  const agent = useAgent({ document, onUpdateDocument: updateDocument, campaignId });
  const bottomRef = React.useRef<HTMLDivElement>(null);

  // Local `/` commands mutate the document without producing a chat message, so
  // they'd otherwise be invisible. A short note keeps the transcript an honest
  // record of everything that changed the email.
  const [notes, setNotes] = React.useState<Array<{ id: string; text: string }>>([]);

  React.useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth", block: "end" });
  }, [agent.messages, notes]);

  function handleCommand(command: AgentCommand) {
    if (command.usesAi && command.prompt) {
      // Writing commands target the selected block when there is one, so
      // /rephrase doesn't quietly rewrite the entire email.
      const block = selectedBlockId
        ? findBlock(document.blocks, selectedBlockId)
        : undefined;
      const reference = block
        ? `@${summarizeBlock(block, 34) || block.type}`
        : null;
      agent.send(
        resolveCommandPrompt(command, reference),
        block ? [block.id] : [],
      );
      return;
    }
    if (!command.apply) return;
    // Goes through the same updater as every other edit, so it lands in the
    // editor's undo stack like a manual change — and costs no model call.
    updateDocument(command.apply);
    setNotes((current) => [...current, { id: createId(), text: `Applied ${command.label}` }]);
  }

  const empty = agent.messages.length === 0 && notes.length === 0;

  return (
    // Fills whatever container it's given — it lives in the left sidebar, so
    // width and borders belong to the sidebar, not to this component.
    <div className="flex min-h-0 flex-1 flex-col overflow-hidden bg-background">
      <header className="flex h-11 shrink-0 items-center justify-between gap-2 border-b border-border px-3">
        <div className="flex items-center gap-2">
          <SparklesIcon className="size-3.5 text-primary" />
          <span className="text-sm font-semibold">Assistant</span>
        </div>
        {agent.messages.length > 0 && (
          <button
            type="button"
            onClick={() => setNotes([])}
            className="text-[11px] text-muted-foreground transition-colors hover:text-foreground"
          >
            Clear
          </button>
        )}
      </header>

      {/* Bring-your-own-key. Delete this line and set
          GOOGLE_GENERATIVE_AI_API_KEY on the server for a private deployment. */}
      <ApiKeyField />

      <ScrollArea className="min-h-0 flex-1">
        <div className="flex flex-col gap-4 p-3">
          {empty ? (
            <div className="flex flex-col gap-3 pt-6">
              <p className="text-sm text-muted-foreground">
                Describe a change and I&apos;ll make it in the email. I keep your
                theme exactly as it is unless you ask me to change it.
              </p>
              <div className="flex flex-col gap-1.5">
                {STARTERS.map((starter) => (
                  <button
                    key={starter}
                    type="button"
                    onClick={() => agent.send(starter)}
                    className="rounded-lg border border-border px-2.5 py-1.5 text-left text-xs text-muted-foreground transition-colors hover:border-ring hover:text-foreground"
                  >
                    {starter}
                  </button>
                ))}
              </div>
            </div>
          ) : (
            agent.messages.map((message, index) => (
              <div key={message.id} className="flex flex-col gap-1.5">
                <Message
                  message={message as unknown as MessageLike}
                  // Only the final message can still be in progress.
                  running={agent.busy && index === agent.messages.length - 1}
                />
                {/* Revert sits on the message that caused the change, so undo is
                    where the user is already looking. */}
                {agent.canRevert && agent.revertMessageId === message.id && (
                  <button
                    type="button"
                    onClick={agent.revert}
                    className="flex w-fit items-center gap-1.5 rounded-md px-1.5 py-1 text-[11px] text-muted-foreground transition-colors hover:text-foreground"
                  >
                    <UndoIcon className="size-3" />
                    Revert this change
                  </button>
                )}
              </div>
            ))
          )}

          {/* Sent, but nothing has streamed back yet. Without this the panel
              sits completely still after you hit enter. */}
          {agent.busy &&
            agent.messages[agent.messages.length - 1]?.role === "user" && (
              <ThinkingBubble />
            )}

          {notes.map((note) => (
            <p key={note.id} className="text-xs text-muted-foreground">
              {note.text}
            </p>
          ))}

          {agent.error && (
            <div className="flex gap-2 rounded-lg border border-destructive/30 bg-destructive/5 p-2.5 text-xs text-destructive">
              <AlertCircleIcon className="mt-px size-3.5 shrink-0" />
              <span>{agent.error.message}</span>
            </div>
          )}

          <div ref={bottomRef} />
        </div>
      </ScrollArea>

      <div className="shrink-0 border-t border-border p-2.5">
        <AgentComposer
          document={document}
          busy={agent.busy}
          model={agent.model}
          selectedBlockId={selectedBlockId}
          onModelChange={agent.setModel}
          onStop={agent.stop}
          onRunCommand={handleCommand}
          onSubmit={({ text, references }) => agent.send(text, references)}
        />
      </div>
    </div>
  );
}

"use client";

// Composer for the agent panel.
//
// Visual design adapted from @kokonutui/ai-prompt; the textarea underneath it
// is replaced with Lexical. That swap is the whole reason for the file: `@`
// block references and `/` commands need atomic chips and a keyboard-driven
// menu, which a textarea cannot express and Lexical's node model can.
//
// Two menus, one plugin shape:
//   @  attaches context — picks a block, never acts
//   /  runs a command — most of which are local and cost no model call at all

import * as React from "react";
import { LexicalComposer } from "@lexical/react/LexicalComposer";
import { PlainTextPlugin } from "@lexical/react/LexicalPlainTextPlugin";
import { ContentEditable } from "@lexical/react/LexicalContentEditable";
import { HistoryPlugin } from "@lexical/react/LexicalHistoryPlugin";
import { LexicalErrorBoundary } from "@lexical/react/LexicalErrorBoundary";
import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import {
  LexicalTypeaheadMenuPlugin,
  MenuOption,
  useBasicTypeaheadTriggerMatch,
} from "@lexical/react/LexicalTypeaheadMenuPlugin";
import {
  $createParagraphNode,
  $createTextNode,
  $getRoot,
  $getSelection,
  $isRangeSelection,
  COMMAND_PRIORITY_HIGH,
  KEY_ENTER_COMMAND,
  type TextNode,
} from "lexical";
import { ArrowUp, ChevronDown, Sparkles, Square, X } from "lucide-react";

import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  AGENT_COMMANDS,
  COMMAND_GROUP_ORDER,
  type AgentCommand,
} from "@/lib/agent/commands";
import { AGENT_MODELS } from "@/lib/agent/models";
import { summarizeBlock } from "@/lib/agent/tools";
import { findBlock, type EmailBlock, type EmailDocument } from "@/lib/email/document";
import { cn } from "@/lib/utils";

import { $createMentionNode, $isMentionNode, MentionNode } from "./mention-node";

export type ComposerSubmit = { text: string; references: string[] };

// ─── Menu options ─────────────────────────────────────────────────────────────

class BlockOption extends MenuOption {
  constructor(
    readonly blockId: string,
    readonly label: string,
    readonly blockType: string,
  ) {
    super(blockId);
  }
}

class CommandOption extends MenuOption {
  constructor(readonly command: AgentCommand) {
    super(command.id);
  }
}

/**
 * Shared popover shell so both menus look and behave identically.
 *
 * Positioned against the composer rather than the caret, and rendered inline
 * instead of through the plugin's anchor element. The plugin's anchor is
 * appended to document.body and sized from the caret rect — about 0px wide —
 * so portalling a fixed-width menu into it overflowed the body and shifted the
 * page, and the anchor carries no z-index so the menu sat under the editor
 * chrome. Anchoring to the composer also just reads better in a narrow
 * sidebar: the menu spans the input and opens upward into the conversation.
 */
function MenuShell({ children }: { children: React.ReactNode }) {
  return (
    <div className="absolute bottom-full left-0 right-0 z-50 mb-2 overflow-hidden rounded-xl border border-border bg-popover p-1 shadow-lg">
      <div className="max-h-64 overflow-y-auto overscroll-contain">{children}</div>
    </div>
  );
}

function MenuRow({
  active,
  title,
  subtitle,
  badge,
  onClick,
  onMouseEnter,
}: {
  active: boolean;
  title: string;
  subtitle?: string;
  badge?: React.ReactNode;
  onClick: () => void;
  onMouseEnter: () => void;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      onMouseEnter={onMouseEnter}
      className={cn(
        "flex w-full items-center gap-2 rounded-lg px-2 py-1.5 text-left transition-colors",
        active ? "bg-accent text-accent-foreground" : "hover:bg-accent/50",
      )}
    >
      <span className="min-w-0 flex-1">
        <span className="block truncate text-xs font-medium">{title}</span>
        {subtitle && (
          <span className="block truncate text-[11px] text-muted-foreground">{subtitle}</span>
        )}
      </span>
      {badge}
    </button>
  );
}

// ─── @ blocks ─────────────────────────────────────────────────────────────────

function MentionsPlugin({ document }: { document: EmailDocument }) {
  const [editor] = useLexicalComposerContext();
  const [query, setQuery] = React.useState<string | null>(null);

  const triggerFn = useBasicTypeaheadTriggerMatch("@", { minLength: 0 });

  const options = React.useMemo(() => {
    const flat: Array<{ block: EmailBlock; label: string }> = document.blocks.map((block) => ({
      block,
      label: summarizeBlock(block, 46) || block.type,
    }));

    const needle = (query ?? "").toLowerCase();
    return flat
      // Match content or type, so "@but" finds the button and "@welcome"
      // finds the block whose heading says Welcome.
      .filter(
        ({ block, label }) =>
          !needle ||
          label.toLowerCase().includes(needle) ||
          block.type.toLowerCase().includes(needle),
      )
      .slice(0, 8)
      .map(({ block, label }) => new BlockOption(block.id, label, block.type));
  }, [document.blocks, query]);

  const onSelect = React.useCallback(
    (option: BlockOption, nodeToReplace: TextNode | null, closeMenu: () => void) => {
      editor.update(() => {
        const chip = $createMentionNode(option.blockId, option.label);
        if (nodeToReplace) nodeToReplace.replace(chip);
        else {
          const selection = $getSelection();
          if ($isRangeSelection(selection)) selection.insertNodes([chip]);
        }
        // Trailing space so the next word isn't swallowed into the chip.
        const space = $createTextNode(" ");
        chip.insertAfter(space);
        space.select();
        closeMenu();
      });
    },
    [editor],
  );

  return (
    <LexicalTypeaheadMenuPlugin<BlockOption>
      options={options}
      onQueryChange={setQuery}
      onSelectOption={onSelect}
      triggerFn={triggerFn}
      menuRenderFn={(_anchorRef, { selectedIndex, selectOptionAndCleanUp, setHighlightedIndex }) =>
        options.length ? (
          <MenuShell>
            {options.map((option, i) => (
              <MenuRow
                key={option.blockId}
                active={selectedIndex === i}
                title={option.label}
                subtitle={`${option.blockType} · reference only`}
                onClick={() => {
                  setHighlightedIndex(i);
                  selectOptionAndCleanUp(option);
                }}
                onMouseEnter={() => setHighlightedIndex(i)}
              />
            ))}
          </MenuShell>
        ) : null
      }
    />
  );
}

// ─── / commands ───────────────────────────────────────────────────────────────

function CommandsPlugin({ onRun }: { onRun: (command: AgentCommand) => void }) {
  const [editor] = useLexicalComposerContext();
  const [query, setQuery] = React.useState<string | null>(null);

  const triggerFn = useBasicTypeaheadTriggerMatch("/", { minLength: 0 });

  const options = React.useMemo(() => {
    const needle = (query ?? "").toLowerCase();
    return AGENT_COMMANDS.filter(
      (command) =>
        !needle ||
        command.label.toLowerCase().includes(needle) ||
        command.group.toLowerCase().includes(needle),
    )
      // Group order is the menu's information architecture: parts you insert,
      // then look, then layout, then the ones that spend a model call.
      .sort(
        (a, b) =>
          COMMAND_GROUP_ORDER.indexOf(a.group) - COMMAND_GROUP_ORDER.indexOf(b.group),
      )
      .slice(0, 10)
      .map((command) => new CommandOption(command));
  }, [query]);

  const onSelect = React.useCallback(
    (option: CommandOption, nodeToReplace: TextNode | null, closeMenu: () => void) => {
      editor.update(() => {
        // The command text itself is never part of the message.
        nodeToReplace?.remove();
        closeMenu();
      });
      onRun(option.command);
    },
    [editor, onRun],
  );

  return (
    <LexicalTypeaheadMenuPlugin<CommandOption>
      options={options}
      onQueryChange={setQuery}
      onSelectOption={onSelect}
      triggerFn={triggerFn}
      menuRenderFn={(_anchorRef, { selectedIndex, selectOptionAndCleanUp, setHighlightedIndex }) =>
        options.length ? (
          <MenuShell>
            {options.map((option, i) => (
              <React.Fragment key={option.command.id}>
                {(i === 0 || options[i - 1].command.group !== option.command.group) && (
                  <div className="px-2 pb-1 pt-2 text-[10px] font-semibold uppercase tracking-wider text-muted-foreground/60">
                    {option.command.group}
                  </div>
                )}
                <MenuRow
                  active={selectedIndex === i}
                  title={option.command.label}
                  subtitle={option.command.hint}
                  badge={
                    option.command.usesAi ? (
                      // Makes the cost visible: everything without this badge
                      // is free and instant.
                      <span className="flex shrink-0 items-center gap-1 rounded bg-primary/10 px-1.5 py-0.5 text-[10px] font-medium text-primary">
                        <Sparkles className="size-2.5" />
                        AI
                      </span>
                    ) : null
                  }
                  onClick={() => {
                    setHighlightedIndex(i);
                    selectOptionAndCleanUp(option);
                  }}
                  onMouseEnter={() => setHighlightedIndex(i)}
                />
              </React.Fragment>
            ))}
          </MenuShell>
        ) : null
      }
    />
  );
}

// ─── Submit ───────────────────────────────────────────────────────────────────

/** Read the composer, pulling block ids out of the chips. */
function readComposer(): ComposerSubmit {
  const root = $getRoot();
  const references = root
    .getAllTextNodes()
    .filter($isMentionNode)
    .map((node) => node.getBlockId());
  return {
    text: root.getTextContent(),
    references: [...new Set(references)],
  };
}

function $clearComposer() {
  const root = $getRoot();
  root.clear();
  root.append($createParagraphNode());
}

function SubmitPlugin({
  onSubmit,
  onEmptyChange,
}: {
  onSubmit: (value: ComposerSubmit) => void;
  onEmptyChange: (empty: boolean) => void;
}) {
  const [editor] = useLexicalComposerContext();

  React.useEffect(
    () =>
      editor.registerUpdateListener(({ editorState }) => {
        onEmptyChange(!editorState.read(() => $getRoot().getTextContent()).trim());
      }),
    [editor, onEmptyChange],
  );

  React.useEffect(
    () =>
      editor.registerCommand(
        KEY_ENTER_COMMAND,
        (event) => {
          // Shift+Enter is a newline. Plain Enter sends — chat convention.
          if (event?.shiftKey) return false;
          event?.preventDefault();
          const value = editor.getEditorState().read(readComposer);
          if (!value.text.trim()) return true;
          onSubmit(value);
          editor.update($clearComposer);
          return true;
        },
        COMMAND_PRIORITY_HIGH,
      ),
    [editor, onSubmit],
  );

  return null;
}

/** Send/stop button — inside the provider so it can read editor state. */
function SendButton({
  busy,
  empty,
  onSubmit,
  onStop,
}: {
  busy: boolean;
  empty: boolean;
  onSubmit: (value: ComposerSubmit) => void;
  onStop: () => void;
}) {
  const [editor] = useLexicalComposerContext();

  if (busy) {
    return (
      <button
        type="button"
        aria-label="Stop"
        onClick={onStop}
        className="rounded-lg bg-black/5 p-2 transition-colors hover:bg-black/10 dark:bg-white/5 dark:hover:bg-white/10"
      >
        <Square className="size-4 fill-current" />
      </button>
    );
  }

  return (
    <button
      type="button"
      aria-label="Send message"
      disabled={empty}
      onClick={() => {
        const value = editor.getEditorState().read(readComposer);
        if (!value.text.trim()) return;
        onSubmit(value);
        editor.update($clearComposer);
      }}
      className="rounded-lg bg-black/5 p-2 transition-colors hover:bg-black/10 disabled:cursor-not-allowed dark:bg-white/5 dark:hover:bg-white/10"
    >
      <ArrowUp className={cn("size-4 transition-opacity", empty ? "opacity-30" : "opacity-100")} />
    </button>
  );
}

// ─── Composer ─────────────────────────────────────────────────────────────────

export function AgentComposer({
  document,
  busy,
  model,
  selectedBlockId,
  onModelChange,
  onSubmit,
  onRunCommand,
  onStop,
  placeholder = "Ask for a change, @ a block, / for commands",
}: {
  document: EmailDocument;
  busy: boolean;
  model: string;
  /** Block currently selected on the canvas, auto-attached as context. */
  selectedBlockId?: string;
  onModelChange: (model: string) => void;
  onSubmit: (value: ComposerSubmit) => void;
  onRunCommand: (command: AgentCommand) => void;
  onStop: () => void;
  placeholder?: string;
}) {
  const [empty, setEmpty] = React.useState(true);
  const activeModel = AGENT_MODELS.find((m) => m.id === model) ?? AGENT_MODELS[0];

  // Selecting a block on the canvas attaches it as context automatically, so
  // "make this shorter" resolves to the block you're looking at without
  // anyone typing an @ first.
  //
  // Shown as a pill above the input rather than injected as a chip inside it:
  // a chip that rewrites itself every time the canvas selection changes would
  // fight the user mid-sentence and move their caret. Dismissing is per-block,
  // so re-selecting or picking a different block re-attaches.
  const [dismissedId, setDismissedId] = React.useState<string | null>(null);
  const attachedId =
    selectedBlockId && selectedBlockId !== dismissedId ? selectedBlockId : null;
  const attachedBlock = attachedId ? findBlock(document.blocks, attachedId) : undefined;
  const attachedLabel = attachedBlock
    ? summarizeBlock(attachedBlock, 34) || attachedBlock.type
    : null;

  function handleSubmit(value: ComposerSubmit) {
    // Merge the auto-attached block in, without duplicating an explicit @.
    const references = attachedId
      ? [...new Set([...value.references, attachedId])]
      : value.references;
    onSubmit({ ...value, references });
  }

  return (
    <LexicalComposer
      initialConfig={{
        namespace: "letterstack-agent-composer",
        nodes: [MentionNode],
        theme: { paragraph: "m-0" },
        onError: (error) => console.error("Composer error", error),
      }}
    >
      {/* relative: both typeahead menus position against this box. */}
      <div className="relative rounded-2xl bg-black/5 p-1.5 dark:bg-white/5">
        {attachedLabel && (
          <div className="flex items-center gap-1.5 px-1.5 pb-1 pt-1">
            <span className="flex min-w-0 items-center gap-1 rounded-md bg-primary/12 py-0.5 pl-1.5 pr-1 text-[11px] font-medium text-primary">
              <span className="truncate">@{attachedLabel}</span>
              <button
                type="button"
                aria-label="Detach selected block"
                onClick={() => setDismissedId(attachedId)}
                className="shrink-0 rounded-sm p-0.5 hover:bg-primary/20"
              >
                <X className="size-2.5" />
              </button>
            </span>
            <span className="shrink-0 text-[10px] text-muted-foreground">selected</span>
          </div>
        )}

        <div className="relative px-2.5 py-2">
          <PlainTextPlugin
            contentEditable={
              <ContentEditable
                className="max-h-44 min-h-[3rem] w-full overflow-y-auto text-sm leading-relaxed outline-none"
                aria-label="Message the assistant"
              />
            }
            placeholder={
              <div className="pointer-events-none absolute left-2.5 top-2 select-none text-sm text-muted-foreground">
                {placeholder}
              </div>
            }
            ErrorBoundary={LexicalErrorBoundary}
          />
        </div>

        <div className="flex items-center justify-between gap-2 pl-1 pr-1 pb-0.5">
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button
                variant="ghost"
                className="flex h-8 items-center gap-1 rounded-md px-2 text-xs hover:bg-black/10 dark:hover:bg-white/10"
              >
                {activeModel.label}
                <ChevronDown className="size-3 opacity-50" />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="start" className="min-w-[13rem]">
              {AGENT_MODELS.map((entry) => (
                <DropdownMenuItem key={entry.id} onSelect={() => onModelChange(entry.id)}>
                  <span className="flex flex-col">
                    <span className="text-xs font-medium">{entry.label}</span>
                    <span className="text-[11px] text-muted-foreground">{entry.hint}</span>
                  </span>
                </DropdownMenuItem>
              ))}
            </DropdownMenuContent>
          </DropdownMenu>

          <SendButton busy={busy} empty={empty} onSubmit={handleSubmit} onStop={onStop} />
        </div>

        <SubmitPlugin onSubmit={handleSubmit} onEmptyChange={setEmpty} />
        <MentionsPlugin document={document} />
        <CommandsPlugin onRun={onRunCommand} />
        <HistoryPlugin />
      </div>
    </LexicalComposer>
  );
}

import {
  $applyNodeReplacement,
  TextNode,
  type EditorConfig,
  type LexicalNode,
  type NodeKey,
  type SerializedTextNode,
  type Spread,
} from "lexical";

/**
 * An `@block` chip in the composer.
 *
 * Extends TextNode rather than DecoratorNode so the chip still participates in
 * normal text flow and selection, then switches to `token` mode — which is what
 * makes it atomic: one backspace removes the whole reference instead of eating
 * it a character at a time, and the caret can never land inside it.
 *
 * The chip's visible text is the block's summary; `blockId` is what actually
 * gets sent to the model. That separation is the point of the feature — users
 * pick by content, the agent receives an id.
 */

export type SerializedMentionNode = Spread<
  { blockId: string },
  SerializedTextNode
>;

const CHIP_CLASS =
  "rounded bg-primary/12 px-1 py-px text-primary font-medium";

export class MentionNode extends TextNode {
  __blockId: string;

  static getType(): string {
    return "mention";
  }

  static clone(node: MentionNode): MentionNode {
    return new MentionNode(node.__blockId, node.__text, node.__key);
  }

  constructor(blockId: string, text: string, key?: NodeKey) {
    super(text, key);
    this.__blockId = blockId;
  }

  getBlockId(): string {
    return this.getLatest().__blockId;
  }

  createDOM(config: EditorConfig): HTMLElement {
    const dom = super.createDOM(config);
    dom.className = CHIP_CLASS;
    dom.setAttribute("data-block-id", this.__blockId);
    return dom;
  }

  static importJSON(serialized: SerializedMentionNode): MentionNode {
    return $createMentionNode(serialized.blockId, serialized.text);
  }

  exportJSON(): SerializedMentionNode {
    return {
      ...super.exportJSON(),
      blockId: this.__blockId,
      type: "mention",
      version: 1,
    };
  }

  isTextEntity(): boolean {
    return true;
  }
}

export function $createMentionNode(blockId: string, label: string): MentionNode {
  const node = new MentionNode(blockId, `@${label}`);
  // Atomic: selection treats the chip as one unit.
  node.setMode("token");
  return $applyNodeReplacement(node);
}

export function $isMentionNode(node: LexicalNode | null | undefined): node is MentionNode {
  return node instanceof MentionNode;
}

"use client";

// Bring-your-own-key field for the agent panel.
//
// This exists because the playground is public and the assistant is not free to
// run. In a private deployment, set GOOGLE_GENERATIVE_AI_API_KEY on the server
// and delete this component — the API route already falls back to it, so the
// panel keeps working with no key field at all.

import * as React from "react";
import { CheckIcon, ExternalLinkIcon, KeyRoundIcon, XIcon } from "lucide-react";

import { useApiKey } from "@/lib/agent/api-key";
