              }}
              placeholder={hasKey ? "Replace key..." : "AIza..."}
              autoComplete="off"
              spellCheck={false}
              className="min-w-0 flex-1 rounded-md border border-border bg-background px-2 py-1.5 font-mono text-xs outline-none focus-visible:ring-2 focus-visible:ring-ring"
            />
            <button
              type="button"
              onClick={save}
              disabled={!draft.trim()}
              className="shrink-0 rounded-md bg-primary px-2.5 py-1.5 text-xs font-medium text-primary-foreground transition-opacity disabled:opacity-40"
            >
              Save
            </button>
            {hasKey && (
              <button
                type="button"
                onClick={() => {
                  setApiKey("");
                  setDraft("");
                }}
                aria-label="Remove stored key"
                className="shrink-0 rounded-md border border-border px-1.5 text-muted-foreground transition-colors hover:text-foreground"
              >
                <XIcon className="size-3.5" />
              </button>
            )}
          </div>

          <p className="text-[11px] leading-relaxed text-muted-foreground">
            Kept in this browser&apos;s local storage and sent to this app&apos;s
            own route, which forwards it to Google. Never logged, never stored on
            the server. Use a free-tier key and revoke it when you are done.
          </p>

          <a
            href="https://aistudio.google.com/apikey"
            target="_blank"
            rel="noreferrer noopener"
            className="inline-flex w-fit items-center gap-1 text-[11px] text-primary hover:underline"
          >
            Get a free key
            <ExternalLinkIcon className="size-3" />
          </a>
        </div>
      )}
    </div>
  );
}

"use client";

// Our agent loop.
//
// The AI SDK is used strictly as transport — it streams one model turn and
// hands us tool calls. Every decision that makes this an agent is ours and
// lives in this file: which tools exist, how they're applied, what context each
// turn carries, when the loop continues or stops, and how a turn is undone.
// There is no ToolLoopAgent and no HarnessAgent here on purpose.
//
// The loop:
//   send  → server makes ONE model call → tool calls stream back
//         → we apply each to the EmailDocument synchronously
//         → we decide whether to continue
//         → repeat, or stop
//
// Tools run here rather than on the server so edits land in React state
// immediately and the user watches the email change. The trade is that the
// server can't see the document, which is why context.ts rebuilds a summary
// each turn.

import * as React from "react";
import { useChat } from "@ai-sdk/react";
import { DefaultChatTransport, lastAssistantMessageIsCompleteWithToolCalls } from "ai";

import type { EmailDocument } from "@/lib/email/document";
import { applyAgentTool, isAgentToolName } from "./tools";
import { buildAgentContext } from "./context";
import { readStoredApiKey } from "./api-key";
import { DEFAULT_AGENT_MODEL, MAX_AGENT_STEPS } from "./models";

/**
 * How many completed user turns of history to resend.
 *
 * Every request carries the whole conversation, so without a cap the cost of a
 * turn grows with the length of the chat — measured at ~3.6k tokens on the
 * first call climbing past 11.9k by the seventeenth, which burns a monthly
 * budget in an afternoon. Older turns are also the least useful context here:
 * `buildAgentContext` re-derives the document state fresh on every request, so
 * stale tool results describe an email that has since changed.
 */
const HISTORY_TURNS = 3;

/**
 * Trim to the last few turns, cutting only at user-message boundaries.
 *
 * Slicing at an arbitrary index can orphan a tool call from its result, which
 * providers reject outright, so the cut always lands on a user message — the
 * one place the transcript is guaranteed to be between tool sequences.
 */
function trimHistory<T extends { role: string }>(messages: T[]): T[] {
  const userIndexes = messages.reduce<number[]>((acc, message, index) => {
    if (message.role === "user") acc.push(index);
    return acc;
  }, []);

  if (userIndexes.length <= HISTORY_TURNS) return messages;
  return messages.slice(userIndexes[userIndexes.length - HISTORY_TURNS]);
}

export type AgentTurn = {
  /** Document as it was before this turn — restored by revert(). */
  snapshot: EmailDocument;
  /** Assistant message id this turn produced, once known. */
  messageId?: string;
};

export type UseAgentOptions = {
  /** Live document. Read at call time so tools never see a stale copy. */
  document: EmailDocument;
  /** Same updater the inspector and canvas use — one write path for everything. */
  onUpdateDocument: (updater: (current: EmailDocument) => EmailDocument) => void;
  campaignId?: string;
};

export function useAgent({ document, onUpdateDocument, campaignId }: UseAgentOptions) {
  const [model, setModel] = React.useState(DEFAULT_AGENT_MODEL);

  // Mirrors the document synchronously. Several tool calls can arrive in one
  // tick, and React state wouldn't have flushed between them — reading from a
  // ref keeps each call operating on the result of the previous one.
  const documentRef = React.useRef(document);
  React.useEffect(() => {
    documentRef.current = document;
  }, [document]);

  // Block ids the user @-referenced, staged by the composer for the next send.
  const pendingReferences = React.useRef<string[]>([]);

  // Snapshot for the turn in flight, so the whole turn reverts as one action
  // rather than one undo step per tool call.
  const [lastTurn, setLastTurn] = React.useState<AgentTurn | null>(null);
  const turnSnapshot = React.useRef<EmailDocument | null>(null);

  const transport = React.useMemo(
    () =>
      new DefaultChatTransport({
        api: "/api/agent/chat",
        // Rebuilt per request, not per mount: by step 3 of a turn the document
        // has already changed, and the model must see the current state.
        prepareSendMessagesRequest: ({ messages }) => ({
          body: {
            messages: trimHistory(messages),
            model,
            campaignId,
            // Read at send time, not at mount: the user can paste a key into
            // the panel mid-conversation and the next turn should use it.
            apiKey: readStoredApiKey(),
            context: buildAgentContext({
              document: documentRef.current,
              references: pendingReferences.current,
            }),
          },
        }),
      }),
    [model, campaignId],
  );

  const chat = useChat({
    transport,

    // Continue automatically once every tool call in the turn has a result.
    // This is the loop's edge: the server does one call per request, so
    // resubmitting is what makes it multi-step.
    sendAutomaticallyWhen: lastAssistantMessageIsCompleteWithToolCalls,

    onToolCall({ toolCall }) {
      // Dynamic tools have no compile-time name; we don't register any.
      if (toolCall.dynamic) return;

      const name = toolCall.toolName;
      if (!isAgentToolName(name)) {
        chat.addToolOutput({
          tool: name,
          toolCallId: toolCall.toolCallId,
          state: "output-error",
          errorText: `Unknown tool "${name}".`,
        });
        return;
      }

      try {
        const before = documentRef.current;
        const { document: next, output, failed } = applyAgentTool(before, name, toolCall.input);

        if (!failed && next !== before) {
          documentRef.current = next;
          onUpdateDocument(() => next);
        }

        // Not awaited — awaiting inside onToolCall can deadlock the stream.
        chat.addToolOutput({
          tool: name,
          toolCallId: toolCall.toolCallId,
          ...(failed
            ? { state: "output-error" as const, errorText: output }
            : { output }),
        });
      } catch (err) {
        chat.addToolOutput({
          tool: name,
          toolCallId: toolCall.toolCallId,
          state: "output-error",
          errorText: err instanceof Error ? err.message : "Tool failed.",
        });
      }
    },
  });

  // Close the turn when the stream settles, recording which message owns the
  // snapshot so the revert button can be attached to it.
  React.useEffect(() => {
    if (chat.status !== "ready" || !turnSnapshot.current) return;
    const snapshot = turnSnapshot.current;
    turnSnapshot.current = null;
    pendingReferences.current = [];
    const lastAssistant = [...chat.messages].reverse().find((m) => m.role === "assistant");
    setLastTurn({ snapshot, messageId: lastAssistant?.id });
  }, [chat.status, chat.messages]);

  const send = React.useCallback(
    (text: string, references: string[] = []) => {
      const trimmed = text.trim();
      if (!trimmed || chat.status === "streaming" || chat.status === "submitted") return;

      pendingReferences.current = references;
      // Capture before any tool runs so revert() restores the pre-turn state.
      turnSnapshot.current = documentRef.current;
      setLastTurn(null);
      chat.sendMessage({ text: trimmed });
    },
    [chat],
  );

  // Undo everything the last turn did, in one action. Left unmemoized — the
  // React Compiler handles this, and a manual useCallback here conflicts with
  // the dependencies it infers.
  function revert() {
    if (!lastTurn) return;
    const snapshot = lastTurn.snapshot;
    documentRef.current = snapshot;
    onUpdateDocument(() => snapshot);
    setLastTurn(null);
  }

  const busy = chat.status === "streaming" || chat.status === "submitted";

  return {
    messages: chat.messages,
    status: chat.status,
    error: chat.error,
    busy,
    send,
    stop: chat.stop,
    revert,
    canRevert: lastTurn !== null,
    revertMessageId: lastTurn?.messageId,
    model,
    setModel,
    maxSteps: MAX_AGENT_STEPS,
  };
}

// The agent's tool surface — one file so the model's schemas and the code that
// executes them can never drift apart.
//
// Every tool is a thin wrapper over a helper that already exists in
// lib/email/document.ts, which is what keeps the "canvas is the only editing
// surface" rule intact: the agent is just another writer into the same
// EmailDocument, exactly like the inspector panel. It has no path to HTML that
// bypasses compileEmailDocument(), and deliberately no access to sending,
// saving, recipients, or the From address.
//
// applyAgentTool is a pure function (document in, document out) so the whole
// tool layer can be exercised without mounting React or calling a model.

import { z } from "zod";

import {
  createBlock,
  duplicateBlock,
  findBlock,
  insertBlockAtIndex,
  removeBlock,
  reorderBlocks,
  touchDocument,
  updateBlock,
  type EmailBlock,
  type EmailDocument,
} from "@/lib/email/document";
import { normalizeRawHtml } from "@/lib/email/normalize-raw-html";

const BLOCK_TYPES = [
  "text",
  "heading",
  "paragraph",
  "image",
  "button",
  "divider",
  "spacer",
  "columns",
  "articleCard",
  "rawHtml",
  "video",
  "social",
  "logo",
  "footer",
] as const;

/** Block fields that hold rich text as HTML rather than a plain string. */
const RICH_TEXT_FIELDS = new Set(["heading", "body", "text", "headline"]);

/**
 * Appearance fields, deliberately unreachable from updateBlock.
 *
 * This is a structural guarantee rather than a request in the prompt: because
 * the content tool has no colour or padding fields, "make this paragraph
 * shorter" *cannot* also restyle the block. A model that drifts off-theme
 * gets a rejection instead of a recoloured email. Changing these requires
 * setBlockStyle, whose description says it needs an explicit visual request.
 */
const STYLE_FIELDS = new Set([
  "backgroundColor",
  "textColor",
  "paddingTop",
  "paddingBottom",
  "columnBackgroundColor",
  "borderColor",
]);

/** Structural fields no tool may set — changing them corrupts the document. */
const FROZEN_FIELDS = new Set(["id", "type", "blocks", "columns", "links"]);

/**
 * Optional fields that `createBlock` doesn't seed.
 *
 * A plain `key in block` test rejects these, because the property genuinely
 * isn't there until something sets it — which would mean the agent could never
 * add a link to an image, or set a background on a block that has never had
 * one. Every BaseBlock style field is in this position, so without this list
 * setBlockStyle would be unable to style anything at all.
 */
const BASE_OPTIONAL_FIELDS = [
  "backgroundColor",
  "textColor",
  "paddingTop",
  "paddingBottom",
];

const OPTIONAL_FIELDS_BY_TYPE: Partial<Record<EmailBlock["type"], string[]>> = {
  image: ["href"],
  logo: ["href"],
  button: ["fullWidth", "secondaryLabel", "secondaryHref", "secondaryVariant"],
  text: ["eyebrow"],
  columns: ["columnBackgroundColor"],
};

function fieldExistsOnBlock(target: EmailBlock, key: string): boolean {
  if (key in target) return true;
  if (BASE_OPTIONAL_FIELDS.includes(key)) return true;
  return (OPTIONAL_FIELDS_BY_TYPE[target.type] ?? []).includes(key);
}

/** Every field a given tool may set on this block, for error messages. */
function settableFields(target: EmailBlock, styling: boolean): string[] {
  const all = new Set([
    ...Object.keys(target),
    ...BASE_OPTIONAL_FIELDS,
    ...(OPTIONAL_FIELDS_BY_TYPE[target.type] ?? []),
  ]);
  return [...all].filter(
    (key) => !FROZEN_FIELDS.has(key) && STYLE_FIELDS.has(key) === styling,
  );
}

/**
 * Models reliably write prose but unreliably remember that these fields are
 * HTML. Wrapping bare text keeps the canvas and compiler from rendering a
 * stray unwrapped string.
 */
function asRichText(value: unknown): unknown {
  if (typeof value !== "string") return value;
  const trimmed = value.trim();
  if (!trimmed) return "";
  return /^</.test(trimmed) ? trimmed : `<p>${trimmed}</p>`;
}

// ─── Value validation ─────────────────────────────────────────────────────────
// Checking that a field *exists* is not enough. Without these, a model can
// write align:"diagonal", level:7, or width:-50 — all of which are accepted by
// a plain key check and then render as garbage.

type FieldCheck =
  | { ok: true; value: unknown }
  | { ok: false; message: string };

const pass = (value: unknown): FieldCheck => ({ ok: true, value });
const failField = (message: string): FieldCheck => ({ ok: false, message });

function enumOf(...allowed: string[]) {
  return (value: unknown): FieldCheck =>
    typeof value === "string" && allowed.includes(value)
      ? pass(value)
      : failField(`must be one of ${allowed.join(", ")}`);
}

function boundedNumber(min: number, max: number) {
  return (value: unknown): FieldCheck => {
    const n = typeof value === "string" ? Number(value) : value;
    if (typeof n !== "number" || !Number.isFinite(n)) return failField("must be a number");
    if (n < min || n > max) return failField(`must be between ${min} and ${max}`);
    return pass(n);
  };
}

const colorValue = (value: unknown): FieldCheck =>
  typeof value === "string" && /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.test(value.trim())
    ? pass(value.trim())
    : failField("must be a hex color like #1a1a1a");

const boolValue = (value: unknown): FieldCheck =>
  typeof value === "boolean" ? pass(value) : failField("must be true or false");

/**
 * Explicit for optional fields that may be absent from the block: without a
 * check, the "keep the existing type" fallback has no existing type to compare
 * against and would wave anything through.
 */
const textValue = (value: unknown): FieldCheck =>
  typeof value === "string" ? pass(value) : failField("must be text");

const FIELD_CHECKS: Record<string, (value: unknown) => FieldCheck> = {
  align: enumOf("left", "center", "right"),
  level: boundedNumber(1, 3),
  variant: enumOf("primary", "secondary"),
  secondaryVariant: enumOf("primary", "secondary"),
  imagePosition: enumOf("left", "right"),
  ctaStyle: enumOf("link", "button"),
  borderStyle: enumOf("none", "solid", "dashed", "dotted"),
  valign: enumOf("top", "middle", "bottom"),
  mobile: enumOf("stack", "stack-reverse", "row"),
  showCta: boolValue,
  showImage: boolValue,
  fullWidth: boolValue,
  href: textValue,
  secondaryHref: textValue,
  secondaryLabel: textValue,
  eyebrow: textValue,
  width: boundedNumber(1, 1000),
  height: boundedNumber(0, 400),
  gap: boundedNumber(0, 64),
  cellPadding: boundedNumber(0, 64),
  borderRadius: boundedNumber(0, 64),
  paddingTop: boundedNumber(0, 200),
  paddingBottom: boundedNumber(0, 200),
  backgroundColor: colorValue,
  textColor: colorValue,
  columnBackgroundColor: colorValue,
  borderColor: colorValue,
};

/**
 * Validate one field against the target block. Fields with an explicit check
 * use it; anything else must at least keep the type the block already has, so
 * an array is never replaced by a string.
 */
function checkField(key: string, value: unknown, current: unknown): FieldCheck {
  if (RICH_TEXT_FIELDS.has(key)) {
    return typeof value === "string" ? pass(asRichText(value)) : failField("must be text");
  }

  const check = FIELD_CHECKS[key];
  if (check) return check(value);

  if (current !== undefined && typeof current !== typeof value) {
    return failField(`must be a ${typeof current}`);
  }
  return pass(value);
}

/** Shared merge path for updateBlock and setBlockStyle. */
function mergeFields(
  target: EmailBlock,
  patch: Record<string, unknown>,
  allow: (key: string) => string | null,
): { allowed: Record<string, unknown>; problems: string[] } {
  const allowed: Record<string, unknown> = {};
  const problems: string[] = [];

  for (const [key, value] of Object.entries(patch)) {
    if (FROZEN_FIELDS.has(key)) {
      problems.push(`${key}: cannot be changed`);
      continue;
    }
    const rejection = allow(key);
    if (rejection) {
      problems.push(`${key}: ${rejection}`);
      continue;
    }
    if (!fieldExistsOnBlock(target, key)) {
      problems.push(`${key}: not a field on a ${target.type} block`);
      continue;
    }
    const result = checkField(key, value, (target as Record<string, unknown>)[key]);
    if (!result.ok) {
      problems.push(`${key}: ${result.message}`);
      continue;
    }
    allowed[key] = result.value;
  }

  return { allowed, problems };
}

// ─── Schemas ──────────────────────────────────────────────────────────────────
// Sent to the model. Descriptions are load-bearing: they are the only place the
// model learns the document's conventions.

export const agentTools = {
  readBlock: {
    description:
      "Read one block's full contents. The conversation already includes a summary outline of every block, so only call this when you need a block's exact current values and it was not referenced with @.",
    inputSchema: z.object({
      id: z.string().describe("Block id from the outline."),
    }),
  },

  addBlock: {
    description:
      "Add a new block with sensible placeholder content, then use updateBlock to fill it in. Returns the new block's id.",
    inputSchema: z.object({
      type: z.enum(BLOCK_TYPES).describe("Kind of block to create."),
      index: z
        .number()
        .int()
        .min(0)
        .optional()
        .describe("Position among top-level blocks. Omit to append at the end."),
    }),
  },

  updateBlock: {
    description:
      "Change the CONTENT of an existing block: text, links, image sources, alignment, layout. Only pass fields you are actually changing. Text fields (heading, body, text, headline) hold HTML — use <p>, <strong>, <em>, <a href>. This tool cannot change colors or padding; that is setBlockStyle, and it is intentionally separate so editing copy never alters the design.",
    inputSchema: z.object({
      id: z.string(),
      patch: z
        .record(z.string(), z.unknown())
        .describe("Field name to new value, e.g. { \"body\": \"<p>Hello</p>\" }."),
    }),
  },

  setBlockStyle: {
    description:
      "Override colors or padding on ONE block. Use this only when the user explicitly asks for a visual change to that block. Never use it to 'improve' or 'tidy' a design that was not mentioned — per-block overrides fight the email's global theme and are almost always the wrong tool. If the user wants a look changed across the whole email, use setDocumentSettings instead.",
    inputSchema: z.object({
      id: z.string(),
      patch: z
        .record(z.string(), z.unknown())
        .describe(
          "Any of backgroundColor, textColor, columnBackgroundColor, borderColor (hex like #1a1a1a), paddingTop, paddingBottom (px).",
        ),
    }),
  },

  removeBlock: {
    description: "Delete a block. The document always keeps at least one block.",
    inputSchema: z.object({ id: z.string() }),
  },

  moveBlock: {
    description: "Move a top-level block to a new position.",
    inputSchema: z.object({
      id: z.string(),
      toIndex: z.number().int().min(0).describe("Zero-based destination index."),
    }),
  },

  duplicateBlock: {
    description: "Copy a block, inserting the copy directly after the original.",
    inputSchema: z.object({ id: z.string() }),
  },

  setCustomHtml: {
    description:
      "Write markup into a rawHtml block. The HTML is placed inside a table cell in the email, so send content only — no <!DOCTYPE>, <html>, <head> or <body>. Email-safe markup only: nested tables and inline styles. Flexbox, grid, absolute positioning, CSS variables, <style> blocks and <script> do not work in email clients and will be stripped or flagged. The plain-text version is derived automatically.",
    inputSchema: z.object({
      id: z.string().describe("Id of an existing rawHtml block."),
      html: z.string(),
      label: z.string().optional().describe("Short name shown on the canvas."),
    }),
  },

  setDocumentSettings: {
    description:
      "Change the email's global theme — colors, font, width, padding, button styling. This is the email's design and the user chose it deliberately, so only call this when they explicitly ask to change how the email looks. Never adjust the theme as a side effect of a content request, and never 'improve' colors that were not mentioned. When the user does ask for a visual change, prefer this over restyling blocks one by one.",
    inputSchema: z.object({
      patch: z.record(z.string(), z.unknown()),
    }),
  },

  setSubject: {
    description:
      "Set the email's subject line and/or the preview text shown after it in the inbox.",
    inputSchema: z.object({
      subject: z.string().optional(),
      previewText: z.string().optional(),
    }),
  },
} as const;

export type AgentToolName = keyof typeof agentTools;

export function isAgentToolName(name: string): name is AgentToolName {
  return Object.prototype.hasOwnProperty.call(agentTools, name);
}

// ─── Execution ────────────────────────────────────────────────────────────────

export type AgentToolOutcome = {
  document: EmailDocument;
  /** Fed back to the model as the tool result. Terse — this costs tokens. */
  output: string;
  /** True when the document was left untouched (an error or a no-op). */
  failed?: boolean;
};

function fail(document: EmailDocument, message: string): AgentToolOutcome {
  return { document, output: message, failed: true };
}

/** One-line summary of a block, matching the outline format the model sees. */
function describeBlock(block: EmailBlock): string {
  const preview = summarizeBlock(block);
  return preview ? `${block.id} (${block.type}) — ${preview}` : `${block.id} (${block.type})`;
}

export function summarizeBlock(block: EmailBlock, max = 60): string {
  const raw = (() => {
    switch (block.type) {
      case "text":
        return `${block.eyebrow ?? ""} ${block.heading} ${block.body}`;
      case "heading":
        return block.text;
      case "paragraph":
        return block.body;
      case "articleCard":
        return `${block.headline} ${block.body}`;
      case "button":
        return `${block.label} → ${block.href}`;
      case "image":
        return block.alt || block.src;
      case "logo":
        return block.alt;
      case "video":
        return block.url;
      case "rawHtml":
        return block.label || block.text;
      case "social":
        return block.links.map((l) => l.platform).join(", ");
      case "footer":
        return block.companyName;
      case "spacer":
        return `${block.height}px`;
      case "columns":
        return `${block.columns.length} columns`;
      default:
        return "";
    }
  })();

  const text = raw.replace(/<[^>]*>/g, " ").replace(/\s+/g, " ").trim();
  return text.length > max ? `${text.slice(0, max - 1)}…` : text;
}

/**
 * Apply one tool call. Pure: never mutates `document`, never touches React,
 * never performs I/O.
 */
export function applyAgentTool(
  document: EmailDocument,
  name: string,
  rawInput: unknown,
): AgentToolOutcome {
  if (!isAgentToolName(name)) return fail(document, `Unknown tool "${name}".`);

  const parsed = agentTools[name].inputSchema.safeParse(rawInput ?? {});
  if (!parsed.success) {
    return fail(document, `Invalid input: ${parsed.error.issues.map((i) => `${i.path.join(".")} ${i.message}`).join("; ")}`);
  }
  const input = parsed.data as Record<string, unknown>;

  switch (name) {
    case "readBlock": {
      const block = findBlock(document.blocks, input.id as string);
      if (!block) return fail(document, `No block with id "${input.id}".`);
      return { document, output: JSON.stringify(block) };
    }

    case "addBlock": {
      const block = createBlock(input.type as EmailBlock["type"]);
      const index = Math.min(
        (input.index as number | undefined) ?? document.blocks.length,
        document.blocks.length,
      );
      return {
        document: insertBlockAtIndex(document, index, block),
        output: `Added ${block.type} block "${block.id}" at index ${index}.`,
      };
    }

    case "updateBlock":
    case "setBlockStyle": {
      const id = input.id as string;
      const target = findBlock(document.blocks, id);
      if (!target) return fail(document, `No block with id "${id}".`);

      const styling = name === "setBlockStyle";
      const { allowed, problems } = mergeFields(
        target,
        input.patch as Record<string, unknown>,
        (key) => {
          const isStyle = STYLE_FIELDS.has(key);
          if (styling && !isStyle) {
            return "is content, not styling — use updateBlock";
          }
          if (!styling && isStyle) {
            return "is styling — use setBlockStyle, and only if the user asked for a visual change";
          }
          return null;
        },
      );

      if (Object.keys(allowed).length === 0) {
        const usable = settableFields(target, styling);
        return fail(
          document,
          `Nothing applied. ${problems.join("; ")}. Fields this tool can set on a ${target.type}: ${usable.join(", ") || "none"}.`,
        );
      }

      const next = updateBlock(document, id, (b) => ({ ...b, ...allowed }) as EmailBlock);
      // Rejections are reported rather than swallowed so the model can correct
      // itself on the next step instead of believing the edit fully landed.
      const note = problems.length ? ` Rejected — ${problems.join("; ")}.` : "";
      return {
        document: next,
        output: `Set ${Object.keys(allowed).join(", ")} on "${id}".${note}`,
      };
    }

    case "removeBlock": {
      const id = input.id as string;
      if (!findBlock(document.blocks, id)) return fail(document, `No block with id "${id}".`);
      const next = removeBlock(document, id);
      if (next === document) {
        return fail(document, "Cannot remove the last remaining block.");
      }
      return { document: next, output: `Removed block "${id}".` };
    }

    case "moveBlock": {
      const id = input.id as string;
      const from = document.blocks.findIndex((b) => b.id === id);
      if (from < 0) return fail(document, `"${id}" is not a top-level block.`);
      const to = Math.min(input.toIndex as number, document.blocks.length - 1);
      if (to === from) return { document, output: `"${id}" is already at index ${to}.` };
      return {
        document: reorderBlocks(document, from, to),
        output: `Moved "${id}" from ${from} to ${to}.`,
      };
    }

    case "duplicateBlock": {
      const id = input.id as string;
      if (!findBlock(document.blocks, id)) return fail(document, `No block with id "${id}".`);
      const next = duplicateBlock(document, id);
      const fresh = next.blocks.find(
        (b) => !document.blocks.some((old) => old.id === b.id),
      );
      return { document: next, output: `Duplicated "${id}"${fresh ? ` as "${fresh.id}"` : ""}.` };
    }

    case "setCustomHtml": {
      const id = input.id as string;
      const target = findBlock(document.blocks, id);
      if (!target) return fail(document, `No block with id "${id}".`);
      if (target.type !== "rawHtml") {
        return fail(document, `Block "${id}" is a ${target.type}, not rawHtml. Add a rawHtml block first.`);
      }

      const { html, text, warnings } = normalizeRawHtml(input.html as string);
      if (!html) {
        return fail(document, `Produced no usable HTML. ${warnings.join(" ")}`.trim());
      }

      const label = (input.label as string | undefined) ?? target.label;
      const next = updateBlock(document, id, (b) => ({ ...b, html, text, label }) as EmailBlock);
      // Warnings go back to the model so it can correct itself next step.
      return {
        document: next,
        output: warnings.length
          ? `Set HTML on "${id}", with changes: ${warnings.join(" ")}`
          : `Set HTML on "${id}".`,
      };
    }

    case "setDocumentSettings": {
      const patch = input.patch as Record<string, unknown>;
      const settings = document.settings as unknown as Record<string, unknown>;
      const allowed: Record<string, unknown> = {};
      const problems: string[] = [];

      for (const [key, value] of Object.entries(patch)) {
        if (!(key in settings)) {
          problems.push(`${key}: not a setting`);
          continue;
        }
        // Same value checks as blocks — a color must still be a color here.
        const result = checkField(key, value, settings[key]);
        if (!result.ok) {
          problems.push(`${key}: ${result.message}`);
          continue;
        }
        allowed[key] = result.value;
      }

      if (Object.keys(allowed).length === 0) {
        return fail(document, `No settings applied. ${problems.join("; ")}.`);
      }
      return {
        document: touchDocument({
          ...document,
          settings: { ...document.settings, ...allowed } as EmailDocument["settings"],
        }),
        output: `Updated theme: ${Object.keys(allowed).join(", ")}.${problems.length ? ` Rejected — ${problems.join("; ")}.` : ""}`,
      };
    }

    case "setSubject": {
      const subject = input.subject as string | undefined;
      const previewText = input.previewText as string | undefined;
      if (subject === undefined && previewText === undefined) {
        return fail(document, "Provide subject, previewText, or both.");
      }
      return {
        document: touchDocument({
          ...document,
          subject: subject ?? document.subject,
          settings:
            previewText === undefined
              ? document.settings
              : { ...document.settings, previewText },
        }),
        output: `Updated ${[subject !== undefined && "subject", previewText !== undefined && "preview text"].filter(Boolean).join(" and ")}.`,
      };
    }
  }
}

export { describeBlock };

// Builds what the model sees each turn.
//
// The whole EmailDocument is far too big to send — it's mostly styling scalars,
// and on a free tier the tokens spent on padding values are tokens not spent on
// the user's actual content. So: always send a one-line-per-block outline, send
// full JSON only for blocks the user @-referenced, and let the model pull
// anything else with the readBlock tool.

import type { EmailBlock, EmailDocument } from "@/lib/email/document";
import { findBlock } from "@/lib/email/document";
import { summarizeBlock } from "./tools";

/** One line per block: id, type, and enough content to identify it. */
export function documentOutline(document: EmailDocument): string {
  if (document.blocks.length === 0) return "(empty — the email has no blocks yet)";

  return document.blocks
    .map((block, index) => {
      const summary = summarizeBlock(block, 70);
      const head = `${index}. ${block.id} [${block.type}]`;
      const line = summary ? `${head} ${summary}` : head;
      // Column cells hold their own content, so name them or the model can't
      // address anything inside a columns block.
      if (block.type === "columns") {
        const cells = block.columns
          .map((c, i) => `      cell ${i} ${c.id}: ${stripTags(c.heading)}`)
          .join("\n");
        return `${line}\n${cells}`;
      }
      return line;
    })
    .join("\n");
}

function stripTags(value: string): string {
  return value.replace(/<[^>]*>/g, " ").replace(/\s+/g, " ").trim();
}

/** Full JSON for the blocks the user explicitly pointed at with @. */
export function expandReferences(
  document: EmailDocument,
  referenceIds: string[],
): string | null {
  const found = referenceIds
    .map((id) => findBlock(document.blocks, id))
    .filter((b): b is EmailBlock => Boolean(b));

  if (found.length === 0) return null;
  return found.map((block) => JSON.stringify(block)).join("\n");
}

/**
 * Settings the model needs to write on-brand content. Deliberately a subset —
 * shadow offsets and padding scalars don't help it write copy or markup.
 */
function relevantSettings(document: EmailDocument) {
  const s = document.settings;
  return {
    backgroundColor: s.backgroundColor,
    contentColor: s.contentColor,
    accentColor: s.accentColor,
    linkColor: s.linkColor,
    textColor: s.textColor,
    fontFamily: s.fontFamily,
    maxWidth: s.maxWidth,
    buttonBackgroundColor: s.buttonBackgroundColor,
    buttonTextColor: s.buttonTextColor,
  };
}

export const AGENT_SYSTEM_PROMPT = `You are the editing assistant inside LetterStack, an email campaign builder. You edit the user's email by calling tools. You never write the email as a chat reply — if the user asks for content, put it in the document.

How the document works:
- An email is an ordered list of blocks. Each has an id and a type.
- Text fields (heading, body, text, headline) contain HTML. Use <p> for paragraphs, plus <strong>, <em>, and <a href="">. Do not use headings tags inside them; block type controls hierarchy.
- Colors, fonts and width are global, in document settings. Change those with setDocumentSettings rather than styling every block.
- The email is compiled to table-based, inline-styled HTML for email clients. Flexbox, grid, absolute positioning and CSS variables do not work.

Protecting the design (this matters more than anything else you do):
- The email already has a theme. The user chose those colors, that font and that spacing on purpose. Treat them as fixed.
- Never change the theme, a block's colors, or its padding unless the user explicitly asked for a visual change. "Rewrite this", "make it shorter", "add a section" are content requests — the design must come out identical.
- New blocks inherit the global theme automatically. Do not set colors on them to "match". Setting them is what causes drift.
- Do not improve, modernise, tidy or harmonise a design nobody asked you to touch. If you think the design is wrong, say so in one sentence and leave it alone.
- When you do add content, write it to suit the existing tone and palette rather than introducing a new style.

How to work:
- Make the edit rather than describing it. Prefer several small tool calls over one large speculative one.
- Only touch what was asked for. Do not restyle or rewrite blocks the user did not mention.
- When the user @-references blocks, those are the blocks they mean.
- If a request is ambiguous in a way that matters, make the most reasonable interpretation and say briefly what you assumed. Do not stop to ask unless you genuinely cannot proceed.
- After your edits, reply with one or two short sentences describing what changed. No preamble, no bullet lists, no restating the document.

Keep copy tight and concrete. Match the tone of the existing content. Placeholder text like "Lorem ipsum" or "Your headline here" is never an acceptable final result.`;

export type AgentContextInput = {
  document: EmailDocument;
  /** Block ids the user @-referenced in this message. */
  references?: string[];
};

/**
 * The per-turn context block. Sent as a system message alongside the
 * conversation so it refreshes as the document changes, rather than going stale
 * inside the message history.
 */
export function buildAgentContext({ document, references = [] }: AgentContextInput): string {
  const parts = [
    `Email: ${document.name || "Untitled"}`,
    `Subject: ${document.subject || "(not set)"}`,
    `Preview text: ${document.settings.previewText || "(not set)"}`,
    "",
    "Theme in use — keep these unless a visual change was explicitly requested:",
    JSON.stringify(relevantSettings(document)),
    "",
    `Blocks (${document.blocks.length}):`,
    documentOutline(document),
  ];

  const expanded = expandReferences(document, references);
  if (expanded) {
    parts.push(
      "",
      "The user referenced these blocks — full contents:",
      expanded,
    );
  }

  return parts.join("\n");
}

// The `/` command palette.
//
// The important property: most of these are **local**. Applying a theme preset
// is a deterministic mutation of document.settings, so it needs no model call —
// which means zero tokens and zero requests against the daily free-tier
// ceiling. On a free plan every command that avoids the model is capacity
// handed back to the requests that genuinely need judgement.
//
// Commands that do need judgement are marked `usesAi` and become a prompt, so
// the panel can show which is which rather than silently spending quota.

import themePresetsJson from "@/lib/email/theme-presets.json";
import type {
  EmailBlock,
  EmailDocument,
  EmailDocumentSettings,
} from "@/lib/email/document";
import { createBlock, insertBlockAtIndex, touchDocument } from "@/lib/email/document";

type ThemePreset = {
  id: string;
  name: string;
  description: string;
  settings: Partial<EmailDocumentSettings>;
};

export const THEME_PRESETS = themePresetsJson as unknown as ThemePreset[];

export type CommandGroup = "Templates" | "Theme" | "Layout" | "Writing";

export type AgentCommand = {
  id: string;
  /** Shown in the menu. */
  label: string;
  hint: string;
  group: CommandGroup;
  /** True when running this costs a model call. */
  usesAi: boolean;
  /** Local mutation. Absent for AI commands. */
  apply?: (document: EmailDocument) => EmailDocument;
  /**
   * Prompt submitted on the user's behalf. Present for AI commands.
   * `{ref}` is replaced with the @-reference for the selected block, or with
   * "the whole email" when nothing is selected — so /rephrase targets what the
   * user is looking at rather than rewriting everything by accident.
   */
  prompt?: string;
};

/** Insert a composite block at the end of the email. */
function insertBlock(type: EmailBlock["type"]) {
  return (document: EmailDocument): EmailDocument =>
    insertBlockAtIndex(document, document.blocks.length, createBlock(type));
}

function applyTheme(preset: ThemePreset) {
  return (document: EmailDocument): EmailDocument =>
    touchDocument({
      ...document,
      settings: { ...document.settings, ...preset.settings },
    });
}

function applyWidth(width: number) {
  return (document: EmailDocument): EmailDocument =>
    touchDocument({ ...document, settings: { ...document.settings, maxWidth: width } });
}

