];

/** Order groups appear in the `/` menu. */
export const COMMAND_GROUP_ORDER: CommandGroup[] = [
  "Templates",
  "Theme",
  "Layout",
  "Writing",
];

/**
 * Fill in `{ref}` with whatever the user currently has in focus, so a writing
 * command applies to the selected block instead of the entire email.
 */
export function resolveCommandPrompt(
  command: AgentCommand,
  reference: string | null,
): string {
  if (!command.prompt) return "";
  return command.prompt.replace(/\{ref\}/g, reference ?? "the whole email");
}

export function findCommand(id: string): AgentCommand | undefined {
  return AGENT_COMMANDS.find((command) => command.id === id);
}

// Model registry for the agent panel.
//
// Gemini direct (Google AI Studio) rather than a router, because the free tier
// is the whole constraint here: Google's free tier allows on the order of a
// thousand requests a day, where OpenRouter's free variants allow 50/day
// governed per-account. One agent turn is several model calls, so 50/day is
// not a product. If OpenRouter is added later for model variety, it slots in
// as another `provider` value without touching anything else.
//
// Model ids are taken from the bundled @ai-sdk/google docs for the installed
// provider version, not from memory. Free-tier availability and per-model rate
// limits change without notice and vary by region — confirm in AI Studio
// before relying on any specific number.

export type AgentModel = {
  id: string;
  label: string;
  /** Short line shown under the label in the picker. */
  hint: string;
  provider: "google";
  /** Accepts image attachments in chat. */
  vision: boolean;
  /**
   * Free-tier ceilings, per model.
   *
   * Google meters each model separately, so exhausting one leaves the others
   * usable — which is exactly why the quota gates key on model rather than
   * counting every call against one shared pool.
   *
   * These are researched published figures, not values the API reports back.
   * Google revises them without notice and varies them by region and account
   * age, so treat them as our own conservative ceiling: the provider's 429 is
   * the real authority, and the send path surfaces it when it disagrees.
   */
  dailyRequestLimit: number;
  rpmLimit: number;
  /**
   * Daily token ceiling — the limit that actually bites here.
   *
   * Observed: 3.6 Flash was refused by Google after 19 requests but ~142k
   * tokens in a day, i.e. nowhere near any published request cap. Agent turns
   * carry a document summary and conversation history, so they are token-heavy
   * and cheap in request count, which makes tokens/day the binding constraint
   * and a requests-only view actively misleading.
   *
   * Estimated from that observation, not published — tune via env once you
   * have watched a few more days.
   */
  dailyTokenLimit: number;
};

export const AGENT_MODELS: AgentModel[] = [
  {
    id: "gemini-3.6-flash",
    label: "Gemini 3.6 Flash",
    hint: "Best balance — the default",
    provider: "google",
    vision: true,
    dailyRequestLimit: Number(process.env.NEXT_PUBLIC_AI_RPD_36_FLASH ?? 1500),
    rpmLimit: 10,
    // Google refused this model at ~142k tokens in a day.
    dailyTokenLimit: Number(process.env.NEXT_PUBLIC_AI_TPD_36_FLASH ?? 150_000),
  },
  {
    id: "gemini-3.5-flash",
    label: "Gemini 3.5 Flash",
    hint: "Previous generation, very capable",
    provider: "google",
    vision: true,
    dailyRequestLimit: Number(process.env.NEXT_PUBLIC_AI_RPD_35_FLASH ?? 1500),
    rpmLimit: 10,
    dailyTokenLimit: Number(process.env.NEXT_PUBLIC_AI_TPD_35_FLASH ?? 250_000),
  },
  {
    id: "gemini-3.5-flash-lite",
    label: "Gemini 3.5 Flash Lite",
    hint: "Fastest, use when Flash is exhausted",
    provider: "google",
    vision: true,
    dailyRequestLimit: Number(process.env.NEXT_PUBLIC_AI_RPD_35_LITE ?? 1000),
    rpmLimit: 15,
    dailyTokenLimit: Number(process.env.NEXT_PUBLIC_AI_TPD_35_LITE ?? 250_000),
  },
];

export function findModel(id: string): AgentModel | undefined {
  return AGENT_MODELS.find((model) => model.id === id);
}

export const DEFAULT_AGENT_MODEL = AGENT_MODELS[0].id;

export function isKnownModel(id: string): boolean {
  return AGENT_MODELS.some((m) => m.id === id);
}

export function resolveModelId(requested: string | undefined): string {
  return requested && isKnownModel(requested) ? requested : DEFAULT_AGENT_MODEL;
}

/**
 * How many model calls one user message may cost. This is the most important
 * quota guard in the system: without it a confused model can loop and burn a
 * day's free-tier allowance on a single request. Enforced server-side by
 * counting assistant turns in the submitted history, not just in the client
 * loop, so a modified client cannot raise it.
 *
 * Must stay below GLOBAL_RPM_LIMIT or one turn starves the next. At 8 a real
 * request — add a block, write its HTML, then fix up a few others — could run
 * out of steps before writing its closing summary, which looked from the panel
 * like the assistant had simply stopped.
 */
export const MAX_AGENT_STEPS = Number(process.env.AI_MAX_STEPS ?? 12);

"use client";

import * as React from "react";

/**
 * Bring-your-own-key storage for the agent playground.
 *
 * The hosted SaaS this editor came from keeps the provider key on the server
 * and meters it per account. An open-source playground cannot: there is no
 * account, and shipping a shared key would mean paying for every visitor.
 * So the key is the visitor's own.
 *
 * What that costs, stated plainly because anyone pasting a key deserves to
 * know:
 *
 * - The key is kept in `localStorage` on this origin, and is readable by any
 *   script running here. Use a key scoped to Google AI Studio's free tier, not
 *   one attached to a billing account you care about.
 * - It is sent to this app's own `/api/agent/chat` route on every turn, which
 *   forwards it to Google. It is never logged and never stored server-side.
 * - Revoke it at https://aistudio.google.com/apikey when you are done testing.
 *
 * In your own deployment, delete this file and read the key from an
 * environment variable on the server instead.
 */
const STORAGE_KEY = "letterstack:agent:google-api-key";

export function readStoredApiKey(): string {
  if (typeof window === "undefined") return "";
  try {
    return window.localStorage.getItem(STORAGE_KEY) ?? "";
  } catch {
    // Private mode, or site data blocked. Behave as if no key is set.
    return "";
  }
}

function writeStoredApiKey(key: string) {
  try {
    if (key) window.localStorage.setItem(STORAGE_KEY, key);
    else window.localStorage.removeItem(STORAGE_KEY);
  } catch {
    // Nothing useful to do — the key simply will not survive a reload.
  }
}

/**
 * Reads the key on mount rather than during render, so the server and the first
 * client render agree and React does not report a hydration mismatch.
 */
export function useApiKey() {
  const [apiKey, setApiKeyState] = React.useState("");
  const [loaded, setLoaded] = React.useState(false);

  React.useEffect(() => {
    setApiKeyState(readStoredApiKey());
    setLoaded(true);
  }, []);

  const setApiKey = React.useCallback((key: string) => {
    const trimmed = key.trim();
    setApiKeyState(trimmed);
    writeStoredApiKey(trimmed);
  }, []);

  return { apiKey, setApiKey, loaded, hasKey: apiKey.length > 0 };
}

// The agent's only server surface: make exactly one model call, stream it back.
//
// It deliberately does NOT run a tool loop. Tools are declared without an
// `execute` function, so the SDK forwards every tool call to the browser, where
// the loop in `lib/agent/use-agent.ts` applies it to the EmailDocument in React
// state and decides whether to continue. That keeps edits instant and avoids
// shipping the whole document up and back on every step.
//
// Differences from the hosted version this came from: no auth, no organization,
// and no usage ledger. Those needed a database and an account. Here the caller
// brings their own Google AI Studio key, so there is no shared quota to meter
// and nothing to bill — the only server-side guard left is the step ceiling,
// which protects the caller's own key from a looping model.

import { NextResponse } from "next/server";
import {
  convertToModelMessages,
  createUIMessageStream,
  createUIMessageStreamResponse,
  streamText,
  toUIMessageStream,
  type UIMessage,
} from "ai";
import { createGoogleGenerativeAI } from "@ai-sdk/google";

import { agentTools } from "@/lib/agent/tools";
import { AGENT_SYSTEM_PROMPT } from "@/lib/agent/context";
import {
  AGENT_MODELS,
  findModel,
  MAX_AGENT_STEPS,
  resolveModelId,
} from "@/lib/agent/models";

export const runtime = "nodejs";
export const maxDuration = 60;

// agentTools is already `{ description, inputSchema }` per tool, which is the
// shape streamText expects. Having no `execute` is what marks them client-side:
// the SDK forwards the call to the browser instead of running it here.
const clientTools = agentTools;

/**
 * Model calls already spent on the caller's current message. One turn is one
 * user message followed by N assistant/tool round trips, so counting assistant
 * messages after the last user message gives the step number. Enforced here
 * rather than only in the client loop, otherwise the cap is advisory.
 */
function stepsInCurrentTurn(messages: UIMessage[]): number {
  const lastUser = messages.map((m) => m.role).lastIndexOf("user");
  if (lastUser < 0) return 0;
  return messages.slice(lastUser + 1).filter((m) => m.role === "assistant").length;
}

function bad(status: number, error: string) {
  return NextResponse.json({ ok: false, error }, { status });
}

/**
 * Turn a refusal into a normal assistant message rather than an HTTP error.
 *
 * The client is reading a UI message stream; a JSON error body just surfaces as
 * "an error occurred" with no explanation, which is exactly how a stop ends up
 * looking like the assistant silently died. Streaming the reason back as
 * assistant text means the user reads *why* it stopped, in the conversation,
 * where they are already looking.
 */
function refusal(message: string) {
  return createUIMessageStreamResponse({
    stream: createUIMessageStream({
      execute({ writer }) {
        const id = "refusal";
        writer.write({ type: "text-start", id });
        writer.write({ type: "text-delta", id, delta: message });
        writer.write({ type: "text-end", id });
      },
    }),
  });
}

export async function POST(request: Request) {
  const body = await request.json().catch(() => null);

  const messages = (body?.messages ?? []) as UIMessage[];
  if (!Array.isArray(messages) || messages.length === 0) {
    return bad(400, "No messages provided.");
  }

  // Caller-supplied, per request. Falls back to a server key so a private
  // deployment can drop the panel's key field and configure it as normal.
  const apiKey =
    (typeof body?.apiKey === "string" ? body.apiKey.trim() : "") ||
    process.env.GOOGLE_GENERATIVE_AI_API_KEY ||
    "";

  if (!apiKey) {
    return refusal(
      "No API key yet. Open the key field at the top of this panel and paste a Google AI Studio key — the free tier is enough to try this out. Get one at https://aistudio.google.com/apikey",
    );
  }

  if (stepsInCurrentTurn(messages) >= MAX_AGENT_STEPS) {
    return refusal(
      `I used all ${MAX_AGENT_STEPS} of my steps on that request without finishing. Try asking for a smaller change, or tell me which part to do first.`,
    );
  }

  const modelId = resolveModelId(typeof body?.model === "string" ? body.model : undefined);

  // Rebuilt by the client each turn from the live document, so it reflects
  // edits made moments ago rather than whatever was true when the chat started.
  const documentContext = typeof body?.context === "string" ? body.context : "";

  try {
    // Per-request provider instance: the key belongs to the caller, so it must
    // not be captured in a module-level singleton shared across requests.
    const google = createGoogleGenerativeAI({ apiKey });

    const result = streamText({
      model: google(modelId),
      instructions: documentContext
        ? `${AGENT_SYSTEM_PROMPT}\n\n---\nCurrent email:\n${documentContext}`
        : AGENT_SYSTEM_PROMPT,
      messages: await convertToModelMessages(messages),
      tools: clientTools,
    });

    return createUIMessageStreamResponse({
      stream: toUIMessageStream({
        stream: result.stream,
        onError: (error) => providerMessage(error, modelId),
      }),
    });
  } catch (err) {
    // Deliberately not logging the error object wholesale — provider errors can
    // echo the request, and the request carries the caller's key.
    console.error(
      "POST /api/agent/chat failed:",
      err instanceof Error ? err.message : "Unknown error",
    );
    return refusal(providerMessage(err, modelId));
  }
}

/**
 * Translate a provider failure into something the caller can act on.
 */
function providerMessage(error: unknown, modelId: string): string {
  const raw = error instanceof Error ? error.message : String(error ?? "");
  const model = findModel(modelId);

  if (/api[ _-]?key|unauthenticated|401|403|PERMISSION_DENIED|invalid.*credential/i.test(raw)) {
    return "Google rejected that API key. Check it was copied whole, and that the Generative Language API is enabled for it at https://aistudio.google.com/apikey";
  }

  if (/quota|rate limit|429|RESOURCE_EXHAUSTED/i.test(raw)) {
    const alternatives = AGENT_MODELS.filter((m) => m.id !== modelId)
      .map((m) => m.label)
      .join(" or ");
    return `${model?.label ?? modelId} has hit the limit on your key. Switch to ${alternatives} from the model picker, or try again after midnight UTC.`;
  }

  if (/not found|not supported|unsupported|invalid model/i.test(raw)) {
    return `${model?.label ?? modelId} isn't available on this API key. Pick a different model.`;
  }

  return raw || "The assistant failed.";
}
